namespace sv_c2cd9afcd0de40558866259ae0677dbc.Auth;

// Serializable DTO used to persist auth state from server to WebAssembly.
public sealed class UserInfo
{
    public required string Email { get; set; }
    public required string[] Roles { get; set; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;

namespace sv_c2cd9afcd0de40558866259ae0677dbc.Auth;

// Server-side provider that creates a hardcoded authenticated user and
// persists the claims via PersistentComponentState so the WebAssembly
// runtime can reconstruct the identity after interactive takeover.
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    protected override UserInfo? MapToUserInfo(AuthenticationState authenticationState)
    {
        // We always return our hardcoded user regardless of the incoming state.
        return HardcodedUser;
    }

    protected override ClaimsPrincipal MapToClaimsPrincipal(UserInfo userInfo)
    {
        return BuildClaimsPrincipal(userInfo);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var principal = BuildClaimsPrincipal(HardcodedUser);
        return Task.FromResult(new AuthenticationState(principal));
    }

    internal static ClaimsPrincipal BuildClaimsPrincipal(UserInfo user)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, user.Email),
            new(ClaimTypes.Email, user.Email)
        };

        foreach (var role in user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        return new ClaimsPrincipal(identity);
    }
}

