using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_c2cd9afcd0de40558866259ae0677dbc.Client;

namespace sv_c2cd9afcd0de40558866259ae0677dbc.Auth;

// Server-side provider that creates a hardcoded authenticated user and
// persists the claims into PersistentComponentState so the WebAssembly
// runtime can reconstruct the identity after interactive handoff.
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    private readonly PersistentComponentState _state;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public ServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _state = persistentComponentState;
        _subscription = _state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        _authStateTask ??= Task.FromResult(BuildAuthenticationState());
        return _authStateTask;
    }

    private AuthenticationState BuildAuthenticationState()
    {
        var principal = PersistentAuthenticationStateProvider.BuildClaimsPrincipal(HardcodedUser);
        return new AuthenticationState(principal);
    }

    private Task OnPersistingAsync()
    {
        _state.PersistAsJson(nameof(UserInfo), HardcodedUser);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

